 const planet={...YAYA_PLANET_A.planet,id:'s01',code:'S',name:'沙漠星球',theme:'desert',vowel:'/s/',seed:73,grass:[.10,.04],next:'t01',order:['s'],letters:{s:{color:'#77bcb3',freq:659.25}},quizOthers:['a'],spots:{s:[30,28]},clearSpots:[],tent:[55,-75],props:{tree:12,treeHigh:7,rocks:6,stones:8,plant:14},words:Object.fromEntries([...Array.from({length:5},(_,i)=>['feed'+i,'喂食 '+(i+1)]),...WORD_CARDS.map(w=>[w.id,w.word])]),intro:'小蛇嘶嘶饿啦！<br>认识 <b>S s</b>，变成小蛇爬过沙地，<br>吃掉喜欢的食物。',introVoice:'s01-intro',introSay:'欢迎来到<b>沙漠星球</b>！跟着金色光点，去找小蛇嘶嘶吧！',done:{emoji:'🐍🌵🌅',title:'S s！',text:'嘶嘶吃饱啦！你学会了 <b>S s</b>，<br>还认识了 sun、sock、six、soup、sit。<br>沙漠的星星，为你亮起来了。',voice:'s01-done'}};
 function helpers(T){const root=new T.Group();const mat=c=>new T.MeshStandardMaterial({color:c,flatShading:true,roughness:.85});function p(parent,c,pos,scale,geo=new T.BoxGeometry(1,1,1)){const m=new T.Mesh(geo,mat(c));m.position.set(...pos);m.scale.set(...scale);m.castShadow=m.receiveShadow=true;parent.add(m);return m}return{root,p}}
 function snake(T){const {root,p}=helpers(T),body=new T.Group(),head=new T.Group();root.add(body);body.add(head);head.position.set(0,.68,.25);for(let i=0;i<7;i++){const a=i*.7;p(body,i%2?'#93bf89':'#75a879',[Math.sin(a)*.32,.18,Math.cos(a)*.30-.2],[.26,.24,.30],new T.IcosahedronGeometry(1,1))}p(body,'#8fbb82',[0,.40,.18],[.28,.38,.25]);p(head,'#9ecb91',[0,0,0],[.52,.36,.45],new T.IcosahedronGeometry(.5,1));p(head,'#f2e5ac',[0,-.14,.12],[.38,.10,.30]);for(const x of [-.17,.17]){p(head,'#3e4f48',[x,.06,.235],[.065,.085,.035]);p(head,'#ffffff',[x-.01,.08,.26],[.02,.025,.01]);p(head,'#e8a59a',[x,-.06,.24],[.06,.03,.02])}root.userData.kind='grandma';return{root,body,head}}
