  const el=document.createElement('div');el.id='unicorn-house';el.className='overlay unicorn-house';el.hidden=true;el.innerHTML=`<section class="card house-card" role="dialog" aria-modal="true" aria-labelledby="house-title"><header><div><small>我们的秘密小天地</small><h2 id="house-title">星朵小屋</h2></div><button class="round" data-close aria-label="关闭星朵小屋">×</button></header><div class="pet-preview"><img alt="拖动旋转星朵" draggable="false"><span class="pet-hearts" aria-hidden="true"></span></div><div class="growth"><strong></strong><span class="growth-balance"></span><progress max="1"></progress><small></small></div><div class="pet-actions"><button data-pet>♡ 摸摸</button><button data-feed>🍎 喂苹果</button><button data-profile>换角色</button></div><div class="house-avatars" hidden></div><h3 class="shop-title">星星商店</h3><p class="shop-help">收集星星，装扮你的好朋友</p><div class="pet-shop"></div><p class="house-status" role="status"></p></section>`;document.body.append(el);
  const preview=YayaCharacters.unicorn(T),previewImg=el.querySelector('.pet-preview img');let yaw=-.38,anim=0,raf=0,levelNotice=false,lastFrame=0,open=false;
  function render(){preview.root.rotation.y=yaw;previewImg.src=YayaProfile.portrait(T,renderer,preview.root,{height:.68,distance:3.25,size:240})}
  function draw(time){raf=0;if(!open)return;if(time-lastFrame>65){lastFrame=time;preview.head.rotation.x=Math.sin(time*.008)*.12*anim;preview.tail.rotation.z=Math.sin(time*.006)*.2;preview.legs.forEach((l,i)=>l.rotation.x=Math.sin(time*.009+i)*.2*anim);render();anim=Math.max(0,anim-.025)}if(anim>0)raf=requestAnimationFrame(draw)}
  function celebrate(){anim=1;el.querySelector('.pet-hearts').textContent='♡  ✦  ♡';el.querySelector('.pet-preview').classList.remove('pet-pop');void el.offsetWidth;el.querySelector('.pet-preview').classList.add('pet-pop');if(!raf)raf=requestAnimationFrame(draw);setTimeout(()=>el.querySelector('.pet-hearts').textContent='',1600)}
  function refresh(){style(T,guide.model,bank.level,bank.data.wearing);style(T,preview,bank.level,bank.data.wearing);const level=bank.level,next=LEVELS[level],base=LEVELS[level-1];el.querySelector('.growth strong').textContent=`星朵 · Lv.${level}`;el.querySelector('.growth-balance').textContent=`★ ${bank.balance}`;el.querySelector('progress').value=next?(bank.data.xp-base)/(next-base):1;el.querySelector('.growth small').textContent=next?`再收集 ${next-bank.data.xp} 颗星星就长大啦`:'小翅膀长出来啦，一起去更远的地方！';el.querySelector('.pet-shop').innerHTML=ITEMS.map(i=>{const owned=bank.data.owned.includes(i.id),worn=bank.data.wearing[i.slot]===i.id,poor=!owned&&bank.balance<i.cost;return `<button data-item="${i.id}" class="shop-item ${worn?'is-worn':''} ${poor?'is-poor':''}" aria-disabled="${poor}"><span aria-hidden="true">${i.icon}</span><b>${i.name}</b><small>${owned?(worn?'已穿戴 · 取下':'穿上'):i.cost+' ★'}</small></button>`}).join('');onBalance();if(open)render()}
  function talk(key,fallback){say(fallback,{voice:key,interrupt:true})}
  function nuzzle(feed=false){guide.cheer();celebrate();if(open){el.querySelector('.house-status').textContent=feed?'星朵开心地嚼着苹果。':'星朵蹭了蹭你的手。';if(feed){const apple=document.createElement('span');apple.className='feeding-apple';apple.textContent='🍎';el.querySelector('.pet-preview').append(apple);setTimeout(()=>apple.remove(),1200)}}else{const pos=point(guide.root.position),h=document.createElement('span');h.className='world-hearts';h.textContent='♡ ♡';h.style.left=(pos?.x||innerWidth/2)+'px';h.style.top=(pos?.y||innerHeight/2)+'px';document.body.append(h);setTimeout(()=>h.remove(),1600)}const id=feed?'pet-feed':`pet-${1+Math.floor(Math.random()*8)}`;talk(id,window.YAYA_VOICE_LINES[id]||'我陪你一起探险！')}
  function show(){open=true;el.hidden=false;refresh();el.querySelector('[data-close]').focus();talk('pet-home','欢迎来到星朵小屋，摸摸我吧！')}
  function close(){open=false;el.hidden=true;document.querySelector('#unicorn-open').focus()}
  el.querySelector('[data-close]').onclick=close;el.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const all=[...el.querySelectorAll('button')].filter(b=>b.offsetParent!==null),i=all.indexOf(document.activeElement);if(e.shiftKey&&i===0){e.preventDefault();all.at(-1).focus()}else if(!e.shiftKey&&i===all.length-1){e.preventDefault();all[0].focus()}}});
  el.querySelector('[data-pet]').onclick=()=>nuzzle();el.querySelector('[data-feed]').onclick=()=>nuzzle(true);
  const avatars=el.querySelector('.house-avatars');avatars.innerHTML=['boy','girl'].map(v=>`<button data-avatar="${v}"><img src="${profile.pics[v]}" alt=""><b>${v==='boy'?'男孩':'女孩'}探险家</b></button>`).join('');el.querySelector('[data-profile]').onclick=()=>{avatars.hidden=!avatars.hidden};avatars.onclick=e=>{const b=e.target.closest('[data-avatar]');if(b){profile.select(b.dataset.avatar);el.querySelector('.house-status').textContent=`已换成${b.textContent}`}};
  el.querySelector('.pet-shop').onclick=e=>{const b=e.target.closest('[data-item]');if(!b)return;const id=b.dataset.item;if(bank.data.owned.includes(id)){bank.toggle(id);refresh()}else if(bank.buy(id)){refresh();celebrate();el.querySelector('.house-status').textContent='穿上新装扮啦！'}else{el.querySelector('.house-status').textContent='再收集几颗星星吧。';talk('pet-poor','再收集几颗星星吧。')}};
