    g.fillStyle = '#ffd95a'; g.fillRect(0, 52, 120, 10); g.fillStyle = '#fff6e0'; g.fillRect(0, 74, 120, 8);
    g.fillStyle = 'rgba(255,255,255,.28)'; g.fillRect(26, 38, 10, 70);
